-- Catálogo bilíngue 9/10, parte 4/4 (500 palavras). Execute as quatro partes em ordem.
-- Reexecutável: atualiza definition_pt e example_pt de palavras já importadas.
begin;
do $$ begin if exists (select 1 from (select unnest(array['arts', 'business', 'food', 'general-vocabulary', 'health', 'law', 'politics', 'science', 'sports', 'technical', 'technology']) as slug) required left join public.vocabulary_categories c using (slug) where c.id is null) then raise exception 'Categorias do catálogo ausentes'; end if; end $$;
insert into public.vocabulary_words (word,translation,definition_en,definition_pt,example_en,example_pt,cefr_level,word_type,category_id,frequency_rank)
select v.word,v.translation,v.definition_en,v.definition_pt,v.example_en,v.example_pt,v.cefr_level,v.word_type,c.id,v.frequency_rank
from jsonb_to_recordset($catalog$
[
{"word":"cubism","translation":"cubismo","definition_en":"An early 20th-century avant-garde art movement pioneered by Pablo Picasso and Georges Braque, characterized by the use of geometric shapes, fragmented forms, and multiple perspectives within a single composition.","definition_pt":"Um movimento artístico de vanguarda do início do século XX pioneiro por Pablo Picasso e Georges Braque, caracterizado pelo uso de formas geométricas, formas fragmentadas e perspectivas múltiplas dentro de uma única composição.","example_en":"Cubism revolutionized painting by breaking objects into geometric facets.","example_pt":"O Cubismo revolucionou a pintura, quebrando objetos em facetas geométricas.","cefr_level":"B2","word_type":"noun","category_slug":"arts","frequency_rank":null},
{"word":"cubist","translation":"cubista","definition_en":"Relating to or characteristic of Cubism, an early 20th-century art movement that emphasizes geometric shapes and multiple perspectives.","definition_pt":"Relativo ou característico do Cubismo, um movimento artístico do início do século XX que enfatiza formas geométricas e perspectivas múltiplas.","example_en":"The gallery featured a collection of cubist paintings by Picasso.","example_pt":"A galeria apresentava uma coleção de pinturas cubistas de Picasso.","cefr_level":"B2","word_type":"adjective","category_slug":"arts","frequency_rank":null},
{"word":"cuckooflower","translation":"agrião-dos-prados","definition_en":"A perennial plant with pale pink or white flowers, commonly found in damp meadows and along streams in Europe and North America.","definition_pt":"Uma planta perene com flores rosa-pálidas ou brancas, comumente encontrada em prados úmidos e ao longo de riachos na Europa e América do Norte.","example_en":"The cuckooflower blooms in early spring along the riverbank.","example_pt":"A flor de cuco floresce no início da primavera ao longo da margem do rio.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"cudweed","translation":"gnafálio","definition_en":"A perennial, cottony-white herb native to the southwestern United States.","definition_pt":"Uma erva perene, branca e algodão nativa do sudoeste dos Estados Unidos.","example_en":"The southwestern cudweed has a distinctive white, woolly appearance.","example_pt":"A alga doce do sudoeste tem uma aparência branca e lanosa.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"cufflink","translation":"abotoadura","definition_en":"A piece of jewelry consisting of one of a pair of linked buttons used to fasten the cuffs of a shirt.","definition_pt":"Uma jóia que consiste em um dos botões ligados usados para prender as algemas de uma camisa.","example_en":"He wore silver cufflinks with his tuxedo.","example_pt":"Ele usava abotoaduras de prata com seu smoking.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"culminate","translation":"culminar","definition_en":"To reach the highest point or final stage of something, often after a long process.","definition_pt":"Para alcançar o ponto mais alto ou o estágio final de algo, muitas vezes após um longo processo.","example_en":"The negotiations culminated in a historic peace agreement.","example_pt":"As negociações culminaram em um acordo de paz histórico.","cefr_level":"B2","word_type":"verb","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"culpably","translation":"culpavelmente","definition_en":"In a way that deserves blame or censure; involving fault or guilt.","definition_pt":"De uma forma que merece culpa ou censura, envolvendo culpa ou culpa.","example_en":"The manager acted culpably by ignoring safety regulations.","example_pt":"O gerente agiu culpado ignorando as regras de segurança.","cefr_level":"C2","word_type":"adverb","category_slug":"law","frequency_rank":null},
{"word":"cultivar","translation":"cultivar","definition_en":"A plant variety that has been produced in cultivation by selective breeding, often for specific desirable traits.","definition_pt":"Uma variedade vegetal que tem sido produzida no cultivo por reprodução seletiva, muitas vezes para características desejáveis específicas.","example_en":"The 'Honeycrisp' is a popular apple cultivar known for its sweetness.","example_pt":"O 'Honeycrisp' é uma cultivar de maçã popular conhecida por sua doçura.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"culvert","translation":"galeria","definition_en":"A structure that allows water to flow under a road, railroad, trail, or similar obstruction from one side to the other.","definition_pt":"Uma estrutura que permite que a água flua sob uma estrada, ferrovia, trilha, ou obstrução semelhante de um lado para o outro.","example_en":"The construction crew installed a new culvert under the highway to prevent flooding.","example_pt":"A equipe de construção instalou um novo bueiro sob a estrada para evitar inundações.","cefr_level":"C1","word_type":"noun","category_slug":"technical","frequency_rank":null},
{"word":"cumulus","translation":"cúmulo","definition_en":"A type of cloud that is thick, white, and fluffy, often with a flat base, typically associated with fair weather.","definition_pt":"Um tipo de nuvem que é grossa, branca e fofa, muitas vezes com uma base plana, tipicamente associada com tempo bom.","example_en":"Cumulus clouds dotted the blue sky on a sunny afternoon.","example_pt":"Nuvens de cúmulo pontilharam o céu azul em uma tarde ensolarada.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"cuneiform","translation":"cuneiforme","definition_en":"A system of writing used in ancient Mesopotamia, characterized by wedge-shaped marks made on clay tablets.","definition_pt":"Um sistema de escrita usado na antiga Mesopotâmia, caracterizado por marcas em forma de cunha feitas em tábuas de argila.","example_en":"The museum displayed a clay tablet inscribed with cuneiform.","example_pt":"O museu exibiu uma tábua de argila com cuneiforme.","cefr_level":"C1","word_type":"noun","category_slug":"arts","frequency_rank":null},
{"word":"cunnilingus","translation":"cunilíngua","definition_en":"The act of using the mouth or tongue to stimulate the vulva or clitoris for sexual pleasure.","definition_pt":"O ato de usar a boca ou língua para estimular a vulva ou clitóris para prazer sexual.","example_en":"The couple explored different forms of intimacy, including cunnilingus.","example_pt":"O casal explorou diferentes formas de intimidade, incluindo cunilingus.","cefr_level":"C2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"cunningly","translation":"destramente","definition_en":"In a manner that demonstrates cleverness or ingenuity, often in a subtle way.","definition_pt":"De uma forma que demonstra inteligência ou engenhosidade, muitas vezes de uma forma sutil.","example_en":"The artist cunningly blended colors to create a stunning effect.","example_pt":"O artista misturou as cores para criar um efeito impressionante.","cefr_level":"B2","word_type":"adverb","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"cupful","translation":"xícara","definition_en":"The amount that a cup can contain, often used as a measurement in cooking.","definition_pt":"A quantidade que um copo pode conter, muitas vezes usada como medida na cozinha.","example_en":"Add one cupful of sugar to the mixture.","example_pt":"Adicione um copo cheio de açúcar à mistura.","cefr_level":"A2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"cupola","translation":"cúpula","definition_en":"A small, dome-like structure on top of a building, often used for decoration or to let in light.","definition_pt":"Uma pequena estrutura em cúpula no topo de um prédio, muitas vezes usada para decoração ou para deixar entrar luz.","example_en":"The church's cupola was painted gold and shone in the sun.","example_pt":"A cúpula da igreja foi pintada de ouro e brilhava ao sol.","cefr_level":"C1","word_type":"noun","category_slug":"technical","frequency_rank":null},
{"word":"cuprite","translation":"cuprita","definition_en":"A red or reddish-brown mineral composed of cuprous oxide (Cu2O), which is an important ore of copper.","definition_pt":"Um mineral vermelho ou marrom-avermelhado composto de óxido cuproso (Cu2O), que é um minério importante de cobre.","example_en":"Cuprite is often found in the oxidized zones of copper deposits.","example_pt":"Cuprite é frequentemente encontrada nas zonas oxidadas de depósitos de cobre.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"cupronickel","translation":"cuproníquel","definition_en":"A metallic alloy composed primarily of copper and nickel, typically in a 60/40 ratio, valued for its corrosion resistance and strength.","definition_pt":"Uma liga metálica composta principalmente de cobre e níquel, tipicamente em uma proporção de 60/40, valorizada por sua resistência à corrosão e resistência.","example_en":"Cupronickel is commonly used in marine hardware due to its resistance to saltwater corrosion.","example_pt":"Cupronickel é comumente usado em hardware marinho devido à sua resistência à corrosão de água salgada.","cefr_level":"C1","word_type":"noun","category_slug":"technical","frequency_rank":null},
{"word":"curassow","translation":"mutum","definition_en":"A large, crested, arboreal game bird native to warm parts of the Americas, known for its long legs and tail, and highly valued as game and food.","definition_pt":"Um grande pássaro arbóreo, de crista, nativo de partes quentes das Américas, conhecido por suas longas pernas e cauda, e altamente valorizado como jogo e comida.","example_en":"The curassow is often hunted for its flavorful meat.","example_pt":"O curassow é frequentemente caçado por sua carne saborosa.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
