$catalog$::jsonb) as v(
  word text,translation text,definition_en text,definition_pt text,example_en text,example_pt text,
  cefr_level text,word_type text,category_slug text,frequency_rank integer
)
join public.vocabulary_categories c on c.slug = v.category_slug
on conflict (word_key) do update set translation=excluded.translation, definition_en=excluded.definition_en, definition_pt=excluded.definition_pt, example_en=excluded.example_en, example_pt=excluded.example_pt, cefr_level=excluded.cefr_level, word_type=excluded.word_type, category_id=excluded.category_id, frequency_rank=excluded.frequency_rank, updated_at=now();
